WITH exploded AS (SELECT id, customer_id, created_at, coupon_codes, li_item.product_id, li_item.qty, li_item.price FROM carts LATERAL VIEW EXPLODE(items) e AS li_item), flattened AS (SELECT id, customer_id, created_at, tag FROM exploded LATERAL VIEW EXPLODE(coupon_codes) x AS tag), enriched AS (SELECT a.*, d.segment FROM flattened a INNER JOIN customers d ON a.customer_id = d.id), stats AS (SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, MIN(created_at) AS first_created_at, SORT_ARRAY(COLLECT_SET(tag)) AS tag_list, SORT_ARRAY(COLLECT_SET(segment)) AS segment_list, GROUPING(DATE_TRUNC('HOUR', created_at)) AS grouping_id FROM enriched GROUP BY ROLLUP (DATE_TRUNC('HOUR', created_at))) SELECT hour_window, first_created_at, tag_list, segment_list, grouping_id FROM stats ORDER BY first_created_at
